{
    adcs_vec3_t axis_norm;
    adcs_status_t st;
    double j;
    double omega;
    double omega_raw;
    double omega_next;
    adcs_vec3_t h_next;

    if ((wheel == NULL) || (next_wheel == NULL) || (next_momentum == NULL) || (saturated == NULL)) {
        return ADCS_E_NULL;
    }

    if ((!adcs_is_finite_vec3(&wheel->axis_body)) ||
        (!isfinite(wheel->inertia_kg_m2)) ||
        (!isfinite(wheel->speed_rad_s)) ||
        (!isfinite(motor_torque)) ||
        (!isfinite(dt)) ||
        (!isfinite(speed_limit))) {
        return ADCS_E_RANGE;
    }

    if (wheel->inertia_kg_m2 <= 0.0) {
        return ADCS_E_RANGE;
    }
    if (dt < 0.0) {
        return ADCS_E_RANGE;
    }
    if (speed_limit <= 0.0) {
        return ADCS_E_RANGE;
    }

    j = wheel->inertia_kg_m2;
    omega = wheel->speed_rad_s;

    st = adcs_vec3_normalize(&wheel->axis_body, ADCS_EPS_NORM, &axis_norm);
    if (st != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    omega_raw = omega + motor_torque * dt / j;
    omega_next = ADCS_CLAMP(omega_raw, -speed_limit, speed_limit);

    if (fabs(omega_raw) > speed_limit) {
        *saturated = 1;
    } else {
        *saturated = 0;
    }

    h_next = adcs_vec3_scale(&axis_norm, j * omega_next);

    next_wheel->axis_body = axis_norm;
    next_wheel->inertia_kg_m2 = j;
    next_wheel->speed_rad_s = omega_next;
    *next_momentum = h_next;

    return ADCS_OK;
}
}

